fn test_app(dir: &std::path::Path) -> (axum::Router, String) {
    test_app_for_listener(dir, false, false, ListenerKind::Combined)
}

fn test_app_with_mpp(dir: &std::path::Path, mpp: bool) -> (axum::Router, String) {
    test_app_for_listener(dir, mpp, false, ListenerKind::Combined)
}

fn test_app_for_listener(
    dir: &std::path::Path,
    mpp: bool,
    github: bool,
    listener: ListenerKind,
) -> (axum::Router, String) {
    test_app_for_listener_with_switches(
        dir,
        listener,
        SurfaceSwitches {
            disable_metrics: false,
            features: FeatureSwitches { mpp, github },
            apis: ApiSwitches {
                openai: true,
                anthropic: true,
            },
        },
    )
}

#[derive(Clone, Copy)]
struct SurfaceSwitches {
    disable_metrics: bool,
    features: FeatureSwitches,
    apis: ApiSwitches,
}

#[derive(Clone, Copy)]
struct FeatureSwitches {
    mpp: bool,
    github: bool,
}

#[derive(Clone, Copy)]
struct ApiSwitches {
    openai: bool,
    anthropic: bool,
}

fn test_app_for_listener_with_switches(
    dir: &std::path::Path,
    listener: ListenerKind,
    switches: SurfaceSwitches,
) -> (axum::Router, String) {
    let dir_arg = dir.to_str().expect("UTF-8 test path");
    let mut args = vec![
        "router",
        "--token-secret",
        "network-audit-secret",
        "--data-dir",
        dir_arg,
        "--upstream-provider",
        "anthropic",
        "--upstream-base-url",
        "http://127.0.0.1:9",
    ];
    if switches.features.mpp {
        args.extend([
            "--mpp-enable",
            "--mpp-amount",
            "1.00",
            "--mpp-currency",
            "USD",
            "--mpp-recipient",
            "audit-merchant",
        ]);
    }
    if !switches.apis.openai {
        args.push("--disable-openai-api");
    }
    if switches.disable_metrics {
        args.push("--disable-metrics");
    }
    if !switches.apis.anthropic {
        args.push("--disable-anthropic-api");
    }
    let config = Cli::try_parse_from(args)
        .expect("test CLI parses")
        .into_config()
        .expect("test config is valid");
    let token_manager = TokenManager::new("network-audit-secret");
    let token = token_manager
        .issue_token(1, "network audit client")
        .expect("issue client token");
    let state = AppState {
        client: reqwest::Client::new(),
        token_manager,
        oauth_provider: OAuthProvider::new(dir_arg),
        account_router: None,
        subscription_reader: None,
        subscription_base_url: None,
        subscription_readers: vec![],
        model_catalogs: Arc::new(ModelCatalogCache::new()),
        subscription_cache: Arc::new(TokenCache::new()),
        upstream_base_url: config.upstream_base_url.clone(),
        upstream_provider: config.upstream_provider,
        gonka: None,
        bridge_model: None,
        bridge_model_policy: link_assistant_router::bridge_selection::BridgeModelPolicy::default(),
        crater: None,
        openai_compatible: config.openai_compatible.clone(),
        provider_store: ProviderStore::open(dir, "network-audit-secret").expect("provider store"),
        logger: log_lazy::LogLazy::new(),
        admin: Arc::new(AdminClaim::load(
            Some("network-audit-admin".to_string()),
            dir,
            Duration::from_secs(60),
        )),
        admin_key: Some("network-audit-admin".to_string()),
        allow_anonymous_admin: false,
        metrics: Arc::new(link_assistant_router::metrics::Metrics::default()),
        audit: Arc::new(link_assistant_router::audit::AuditLog::disabled()),
        request_log: Arc::new(link_assistant_router::request_log::RequestLog::new(
            dir.join("requests"),
            1024 * 1024,
        )),
        activitypub_actor_base_url: "https://router.test".to_string(),
        activitypub_public_key_pem:
            link_assistant_router::config::default_activitypub_public_key_pem(),
        mpp: config.mpp.clone(),
        login_manager: link_assistant_router::login::LoginManager::new(config.login.clone()),
        github: if switches.features.github {
            link_assistant_router::github_proxy::GitHubProxyConfig::with_credential(
                "upstream-github-token",
                "http://127.0.0.1:9",
            )
        } else {
            link_assistant_router::github_proxy::GitHubProxyConfig::default()
        },
        max_proxy_request_bytes: link_assistant_router::config::DEFAULT_MAX_PROXY_REQUEST_BYTES,
    };
    (
        link_assistant_router::server_router::router_for_listener(state, &config, listener).layer(
            axum::Extension(axum::extract::ConnectInfo(
                "127.0.0.1:12345".parse::<std::net::SocketAddr>().unwrap(),
            )),
        ),
        token,
    )
}

