        (Method::GET, "/api/services/qwen/v1/models"),
        (Method::POST, "/api/services/qwen/v1/chat/completions"),
        (Method::GET, "/api/services/qwen/v1/chat/completions"),
        (
            Method::GET,
            "/api/services/qwen/v1/chat/completions/chatcmpl_test",
        ),
        (
            Method::POST,
            "/api/services/qwen/v1/chat/completions/chatcmpl_test",
        ),
        (
            Method::DELETE,
            "/api/services/qwen/v1/chat/completions/chatcmpl_test",
        ),
