#[tokio::test]
async fn routing_controls_require_admin_on_management_listeners_without_metrics() {
    for listener in [ListenerKind::Combined, ListenerKind::Admin] {
        let dir = tempfile::tempdir().expect("tempdir");
        let (app, token) = test_app_for_listener_with_switches(
            dir.path(),
            listener,
            SurfaceSwitches {
                disable_metrics: true,
                features: FeatureSwitches {
                    mpp: false,
                    github: false,
                },
                apis: ApiSwitches {
                    openai: true,
                    anthropic: true,
                },
            },
        );
        for (method, path, body) in [
            (
                Method::PATCH,
                "/api/management/routing",
                r#"{"strategy":"round-robin"}"#,
            ),
            (Method::POST, "/api/management/routing/cooldown/reset", "{}"),
        ] {
            for credential in [None, Some(token.as_str())] {
                let result = response(app.clone(), method.clone(), path, credential, body).await;
                assert_eq!(result.status(), StatusCode::UNAUTHORIZED, "{method} {path}");
            }
            let result =
                response(app.clone(), method, path, Some("network-audit-admin"), body).await;
            assert_eq!(
                result.status(),
                StatusCode::CONFLICT,
                "configured route without a pool: {path}"
            );
        }
    }
}

#[tokio::test]
async fn github_cli_aliases_exist_only_on_the_private_adapter_listener() {
    let dir = tempfile::tempdir().expect("tempdir");
    let (combined, token) = test_app_for_listener(dir.path(), false, true, ListenerKind::Combined);

    let canonical = response(
        combined.clone(),
        Method::GET,
        "/api/services/github/api/v3/user",
        None,
        "",
    )
    .await;
    assert_eq!(canonical.status(), StatusCode::UNAUTHORIZED);
    let public_alias = response(combined, Method::GET, "/api/v3/user", Some(&token), "").await;
    assert_eq!(public_alias.status(), StatusCode::NOT_FOUND);

    let (adapter, adapter_token) =
        test_app_for_listener(dir.path(), false, true, ListenerKind::GitHubAdapter);
    for (method, path) in [
        (Method::GET, "/api/v3/user"),
        (Method::POST, "/api/graphql"),
        (Method::GET, "/git/owner/repo.git/info/refs"),
    ] {
        let anonymous = response(adapter.clone(), method.clone(), path, None, "{}").await;
        assert_eq!(anonymous.status(), StatusCode::UNAUTHORIZED, "{path}");
        let authenticated =
            response(adapter.clone(), method, path, Some(&adapter_token), "{}").await;
        assert_ne!(authenticated.status(), StatusCode::NOT_FOUND, "{path}");
    }

    for path in [
        "/api/health",
        "/api/management/tokens",
        "/api/services/github/api/v3/user",
    ] {
        let result = response(adapter.clone(), Method::GET, path, Some(&adapter_token), "").await;
        assert_eq!(result.status(), StatusCode::NOT_FOUND, "{path}");
    }
}

